; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			lea if4_e, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_rep_c:		; call rep
			movea.l (sp)+, a0		; c
			lea var_rep_c, a1
			move.w #255, d1
			subq.w #1, d1
			bmi p_rep_si0_e
p_rep_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_rep_si0
			beq p_rep_si0_z
p_rep_si0_e:
			clr.b (a1)
p_rep_si0_z:
			movea.l (sp)+, a0		; n
			move.w (a0), var_rep_n
			clr.b var_rep_rep
			move.l sp, p_rep_rs
			lea p_rep, sp
			rts
p_rep_r:		; end of rep
			movea.l p_rep_rs, sp
			rts
p_lenof_c:		; call lenof
			movea.l (sp)+, a0		; x
			lea var_lenof_x, a1
			move.w #255, d1
			subq.w #1, d1
			bmi p_lenof_si0_e
p_lenof_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_lenof_si0
			beq p_lenof_si0_z
p_lenof_si0_e:
			clr.b (a1)
p_lenof_si0_z:
			clr.w var_lenof_lenof
			move.l sp, p_lenof_rs
			lea p_lenof, sp
			rts
p_lenof_r:		; end of lenof
			movea.l p_lenof_rs, sp
			rts
p_fill_c:		; call fill
			movea.l (sp)+, a0		; x
			move.l a0, p_fill_a0
			lea var_fill_x, a1
			move.w #255, d1
			subq.w #1, d1
			bmi p_fill_si0_e
