			move.b (a0)+, (a1)+
			dbeq d1, p_fill_si0
			beq p_fill_si0_z
p_fill_si0_e:
			clr.b (a1)
p_fill_si0_z:
			move.l sp, p_fill_rs
			lea p_fill, sp
			rts
p_fill_r:		; end of fill
			movea.l p_fill_a0, a1
			lea var_fill_x, a0
			moveq #0, d1
			move.b -1(a1), d1		; the destination's capacity
			subq.w #1, d1
			bmi p_fill_so0_e
p_fill_so0:
			move.b (a0)+, (a1)+
			dbeq d1, p_fill_so0
			beq p_fill_so0_z
p_fill_so0_e:
			clr.b (a1)
p_fill_so0_z:
			movea.l p_fill_rs, sp
			rts
p_setel_c:		; call setel
			movea.l (sp)+, a0		; a() descriptor
			lea pa_setel_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l sp, p_setel_rs
			lea p_setel, sp
			rts
p_setel_r:		; end of setel
			movea.l p_setel_rs, sp
			rts

